command:
(async () => {
	if (!canvas.tokens.controlled.length) {
		ui.notifications.warn("Please select a token first.");
		return;
	}

	const token = canvas.tokens.controlled[0];
	const actor = token.actor;

	if (!actor) {
		ui.notifications.error("Selected token has no actor.");
		return;
	}

	// Get all conditions as items with the "condition" type
	const conditions = actor.items.filter(item => item.type === "condition");
	if (!conditions.length) {
		ui.notifications.info(`${actor.name} has no conditions.`);
		return;
	}

	const content = `
		<div style="text-align:center;">
			<img src="${actor.img}" width="80" height="80" style="border:1px solid #999;border-radius:8px;margin-bottom:8px;" />
			<h2>${actor.name}</h2>
			<hr>
			<p><strong>Conditions:</strong></p>
			<ul style="list-style:none;padding:0;">
				${conditions.map(c => `<li>• ${c.name}</li>`).join("")}
			</ul>
		</div>
	`;

	new foundry.applications.api.DialogV2({
		window: { title: "Remove Conditions?" },
		content,
		buttons: [{
			action: "remove",
			label: "Remove Conditions",
			default: true,
			callback: async () => {
				for (const cond of conditions) {
					await cond.delete();
				}
				ui.notifications.info(`Removed all conditions from ${actor.name}.`);
			}
		}, {
			action: "cancel",
			label: "Cancel"
		}]
	}).render(true);
})();
